-- Lua 5.1's argument errors (luaL_argerror, luaL_typerror): the function's
-- name quoted, as the calling instruction names it ('?' when called from
-- a Go function such as pcall, or a tail call), "no value" for a missing
-- argument, the self argument not counted for a method ("calling 'x' on
-- bad self"); were "bad argument #1 to rep (string expected, got nil)",
-- "(anonymous)". Errors raised by Go functions get the position of their
-- caller only when it is a Lua function (luaL_where(1)): none when pcall
-- calls them directly, as for assert. io.input/io.output: "FILE*
-- expected" (was "string or file expedted"), nil gives the current file.
local function p(...) print(pcall(...)) end
p(string.rep)
p(string.rep, "x")
p(function() string.rep() end)
p(function() ("x"):rep() end)
p(function() local s = string; s.rep() end)
p(function() local rep = string.rep; rep() end)
p(function() local t = {r = string.rep}; t.r() end)
p(function() local t = {rep = string.rep}; t:rep(2) end)
p(function() local t = {rep = string.rep}; t:rep() end)
p(function() string.rep(nil, 1) end)
p(function() string.rep({}, 1) end)
p(function() return string.rep() end)
p(function() return ("x").rep() end)
p(function() local s = 1; return string.byte(s, {}) end)
p(function() return ("x"):byte({}) end)
p(function() return ("x"):sub() end)
p(function() return string.byte(nil) end)
p(function() return io.lines({}) end)
p(function() return math.floor("x") end)
p(function() return math.floor() end)
p(function() return tostring() end)
p(function() return ipairs() end)
p(function() return ipairs(nil) end)
p(function() for k in pairs(nil) do end end)
p(function() for k in next, nil do end end)
p(function() return table.concat({{}}) end)
p(table.concat, {{}})
p(function() return table.insert(1, 2) end)
p(function() return table.insert({}, 1, 2, 3) end)
p(table.insert, {}, 1, 2, 3)
p(function() return select('x') end)
p(function() return unpack(nil) end)
p(function() return string.format("%d", "x") end)
p(function() return ("x"):format({}) end)
p(function() return os.date({}) end)
p(function() return string.sub() end)
p(function() return tonumber() end)
p(function() return tonumber("1", 99) end)
p(function() return rawget(1) end)
p(function() return getmetatable() end)
p(function() return next(nil) end)
p(function() local m = {} ; function m.f(a) return string.rep(a) end return m.f() end)
p(function() local m = {} ; function m.f(a) return (string.rep(a)) end return m.f() end)
p(function() local m = {} ; function m:f(a) return self:g() end return m:f() end)
p(function() return coroutine.wrap(string.rep)() end)
p(function() local co = coroutine.create(string.rep) return coroutine.resume(co) end)
p(function() local co = coroutine.create(function() local s = string.rep() end) return coroutine.resume(co) end)
p(function() return setmetatable({}, {__index = function(t, k) return string.rep() end}).x end)
p(function() return setmetatable({}, {__index = string.rep}).x end)
p(function() return setmetatable({}, {__add = string.rep}) + 1 end)
p(function() local t = setmetatable({}, {__call = string.rep}) return t() end)
p(function() return table.sort({3, 2, 1}, string.rep) end)
p(function() return string.gsub("x", "x", string.rep) end)
p(function() return xpcall(string.rep, function(m) return "handled: " .. m end) end)
p(assert, false, "boom")
p(assert, nil)
p(assert)
p(function() assert(false, "boom") end)
p(function() assert(false) end)
p(function() assert(nil, 42) end)
p(function() assert() end)
p(function() return io.input({}) end)
p(function() return io.output(true) end)
print(io.type(io.input(nil)), io.input(nil) == io.input())
print(io.type(io.output(nil)), io.output(nil) == io.output())
